/* Hand-made virtual calls (the per-function files called by slot): the vtable pointer of a BASIC is at +0xC. */
struct VTE { short d; short pad; void (*pfn)(); };
#define PVT(p) (*(VTE **)((char *)(p) + 0xC))

struct AREQV { int cb; int cbAlign; };
/* The by-reference form func_001300B8 builds as a temporary. */
struct AREQT : AREQV { AREQT(int c, int a) { cb = c; cbAlign = a; } };

/* An animation curve object (PacNewKind/PacNewKind2), loaded and evaluated through its vtable (pointer at +0). */
struct AC
{
    virtual void Load(CBinaryInputStream *pbis);
    virtual void VUnk2();
    virtual void Eval(float t, float svt, qword *pq1, qword *pq2);
};

/* ASEG::achn entry: the target object (OID, 20 bits) and the sub-object index of the animated XF (10 bits), two flags
   (bit 30: skip in the stand-alone evaluation; bit 31: rotation curve), and the curve. The per-function files read the
   key word three ways, kept as a union. */
struct CHN
{
    union
    {
        struct { unsigned n : 20; unsigned k : 10; unsigned f30 : 1; unsigned f31 : 1; } u;
        struct { int id : 20; int sub : 10; unsigned f30 : 1; unsigned f31 : 1; } s;  /* signed reads */
        unsigned int grf;
    };
    union { AC *pac; int n4; };
};

/* ASEG::aovr entry: value, target OID, curve. */
struct OVR { int x0; int oid; union { AC *pac; int x8; }; };

/* What ASEGA::pactsegFirst / povraFirst link (built by func_0012F9B8). */
struct ACTSEG { int x0; LO *plo; void *pv; int xC; int pad10; int x14; VTE *pvt; int x1C; int x20; ASEGA *pasega; ACTSEG *pactsegNext; };
struct OVRA { int x0; int x4; LO *plo; int xC; OVRA *povraNext; };

/* The XF a channel animates, as func_001300B8 reads it. */
struct M4 { qword a[4]; };
struct XFV { M4 m; char pad[0x94 - 0x40]; int x94; int pad98[2]; XFV *pxfNext; };

struct R94 { char pad[0x94]; void *pv; };

struct LONGU { long l; } __attribute__((packed));

